<template><main v-if="overlay" class="overlay-editor" :class="{'is-preview':previewMode}"><header class="editor-topbar"><RouterLink :to="{name:'CreatorOverlays'}" aria-label="Back to overlays">←</RouterLink><input v-model="overlay.name" aria-label="Overlay name" @change="commit"><label>Canvas<select :value="overlay.resolution.preset" @change="requestResolution($event.target.value)"><option v-for="(preset,key) in RESOLUTION_PRESETS" :key="key" :value="key">{{ preset.label }} · {{ preset.width }}×{{ preset.height }}</option><option value="custom">Custom</option></select></label><button type="button" :class="{active:!previewMode}" @click="previewMode=false">Edit Mode</button><button type="button" :class="{active:previewMode}" @click="previewMode=true">Preview Mode</button><button type="button" :disabled="!history.canUndo" @click="undo">Undo</button><button type="button" :disabled="!history.canRedo" @click="redo">Redo</button><button type="button" class="primary-action" @click="save">Save Local Demo</button><span class="topbar-status">{{ saveStatus }}</span></header><div v-if="!previewMode" class="editor-workspace"><WidgetLibrary @add="addWidget"/><section class="editor-centre"><div class="canvas-tools"><OverlayBackgroundSelector :preview="overlay.preview" @change="changePreview" @upload="uploadReference"/><label><input v-model="showGuides" type="checkbox"> Safe-area guides</label><button type="button" @click="showDemo=!showDemo">Demo events</button></div><OverlayCanvas :overlay="overlay" :selected-id="selectedId" :preview-mode="false" :show-guides="showGuides" @select="selectedId=$event" @change="changeWidget"/><WidgetLayersPanel :widgets="overlay.widgets" :selected-id="selectedId" @select="selectedId=$event" @action="layerAction"/></section><WidgetPropertiesPanel :widget="selectedWidget" @change="changeWidget($event,true)"/></div><div v-else class="preview-workspace"><OverlayCanvas :overlay="overlay" :selected-id="''" :preview-mode="true" :show-guides="false"/><button type="button" class="exit-preview" @click="previewMode=false">Exit Preview Mode</button></div><aside v-if="showDemo&&!previewMode" class="demo-drawer" aria-label="Demo event simulator"><header><div><p class="overlay-kicker">Frontend only</p><h2>Demo Events</h2></div><button type="button" aria-label="Close demo events" @click="showDemo=false">×</button></header><p>Repeatable local events. Nothing is sent to Twitch or the bot.</p><button v-for="topic in DEMO_EVENT_TOPICS" :key="topic" type="button" @click="sendDemo(topic)">{{ demoLabel(topic) }}</button></aside><OverlayBrowserSourceCard v-if="!previewMode" :resolution="overlay.resolution"/><div v-if="resolutionDialog" class="editor-modal" role="dialog" aria-modal="true" aria-labelledby="resolution-title"><form @submit.prevent="applyResolution('scale')"><h2 id="resolution-title">Change canvas resolution</h2><template v-if="resolutionDialog.key==='custom'"><label>Width<input v-model.number="resolutionDialog.width" type="number" min="320" max="7680"></label><label>Height<input v-model.number="resolutionDialog.height" type="number" min="240" max="4320"></label></template><p>Scale widgets proportionally, or retain their current canvas coordinates?</p><div><button type="submit">Scale Layout</button><button type="button" @click="applyResolution('keep')">Keep Coordinates</button><button type="button" @click="resolutionDialog=null">Cancel</button></div></form></div></main><main v-else class="overlay-not-found"><h1>Overlay not found</h1><RouterLink :to="{name:'CreatorOverlays'}">Return to My Overlays</RouterLink></main>
</template>
<script setup>import { computed,onBeforeUnmount,reactive,ref } from 'vue'; import { useRoute } from 'vue-router'; import OverlayBackgroundSelector from '../../components/overlays/OverlayBackgroundSelector.vue';import OverlayBrowserSourceCard from '../../components/overlays/OverlayBrowserSourceCard.vue';import OverlayCanvas from '../../components/overlays/OverlayCanvas.vue';import WidgetLayersPanel from '../../components/overlays/WidgetLayersPanel.vue';import WidgetLibrary from '../../components/overlays/WidgetLibrary.vue';import WidgetPropertiesPanel from '../../components/overlays/WidgetPropertiesPanel.vue';import { createDemoEvent,DEMO_EVENT_TOPICS,demoEventBus } from '../../overlays/demoEventBus.js';import { createHistory } from '../../overlays/overlayHistory.js';import { RESOLUTION_PRESETS } from '../../overlays/overlayModel.js';import { scaleLayout } from '../../overlays/overlayGeometry.js';import { getOverlay,updateOverlay } from '../../overlays/overlayStore.js';import { createWidget } from '../../overlays/widgetRegistry.js'; const route=useRoute();const stored=getOverlay(route.params.overlayId);const overlay=ref(stored?structuredClone(stored):null);const history=reactive(createHistory(overlay.value||{}));const selectedId=ref('');const previewMode=ref(route.query.mode==='preview');const showGuides=ref(false);const showDemo=ref(false);const saveStatus=ref('Unsaved local changes');const resolutionDialog=ref(null);let customUrl='';const selectedWidget=computed(()=>overlay.value?.widgets.find(w=>w.id===selectedId.value)||null);function snapshot(){history.commit(overlay.value);saveStatus.value='Unsaved local changes'}function commit(){snapshot()}function addWidget(type){const widget=createWidget(type,overlay.value,{x:100+overlay.value.widgets.length*25,y:100+overlay.value.widgets.length*25});overlay.value.widgets.push(widget);selectedId.value=widget.id;snapshot()}function changeWidget(next,record=true){const index=overlay.value.widgets.findIndex(w=>w.id===next.id);if(index<0)return;overlay.value.widgets[index]=next;if(record)snapshot()}function normalizeLayers(){[...overlay.value.widgets].sort((a,b)=>a.zIndex-b.zIndex).forEach((w,i)=>w.zIndex=i+1)}function layerAction(action,id){const widget=overlay.value.widgets.find(w=>w.id===id);if(!widget)return;const max=Math.max(...overlay.value.widgets.map(w=>w.zIndex));if(action==='visibility')widget.enabled=!widget.enabled;if(action==='lock')widget.locked=!widget.locked;if(action==='forward')widget.zIndex=Math.min(max,widget.zIndex+1);if(action==='backward')widget.zIndex=Math.max(1,widget.zIndex-1);if(action==='front')widget.zIndex=max+1;if(action==='back')widget.zIndex=0;normalizeLayers();snapshot()}function deleteSelected(){if(!selectedWidget.value)return;overlay.value.widgets=overlay.value.widgets.filter(w=>w.id!==selectedId.value);selectedId.value='';normalizeLayers();snapshot()}function duplicateSelected(){if(!selectedWidget.value)return;const copy=structuredClone(selectedWidget.value);copy.id=`${copy.id}_copy_${Date.now().toString(36)}`;copy.name=`${copy.name} Copy`;copy.frame.x+=20;copy.frame.y+=20;copy.zIndex=Math.max(...overlay.value.widgets.map(w=>w.zIndex))+1;overlay.value.widgets.push(copy);selectedId.value=copy.id;snapshot()}function keyboard(e){const tag=document.activeElement?.tagName;if(['INPUT','TEXTAREA','SELECT'].includes(tag)||previewMode.value)return;if((e.key==='Delete'||e.key==='Backspace')&&selectedWidget.value){e.preventDefault();deleteSelected()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'&&selectedWidget.value){e.preventDefault();duplicateSelected()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}}window.addEventListener('keydown',keyboard);onBeforeUnmount(()=>{window.removeEventListener('keydown',keyboard);if(customUrl)URL.revokeObjectURL(customUrl)});function undo(){overlay.value=history.undo();saveStatus.value='Unsaved local changes'}function redo(){overlay.value=history.redo();saveStatus.value='Unsaved local changes'}function save(){updateOverlay(overlay.value);saveStatus.value='Saved in this browser';history.replace(overlay.value)}function changePreview(next){overlay.value.preview=next;snapshot()}function uploadReference(e){const file=e.target.files?.[0];if(!file)return;if(customUrl)URL.revokeObjectURL(customUrl);customUrl=URL.createObjectURL(file);overlay.value.preview={...overlay.value.preview,backgroundType:'custom',customImageUrl:customUrl};saveStatus.value='Custom reference is session-only';snapshot()}function sendDemo(topic){demoEventBus.publish(createDemoEvent(topic,overlay.value.id))}function demoLabel(topic){return `Send test ${topic.replaceAll('.',' ').replaceAll('_',' ')}`}function requestResolution(key){const preset=RESOLUTION_PRESETS[key];resolutionDialog.value={key,width:preset?.width||overlay.value.resolution.width,height:preset?.height||overlay.value.resolution.height}}function applyResolution(mode){const next={width:Number(resolutionDialog.value.width),height:Number(resolutionDialog.value.height),preset:resolutionDialog.value.key,label:resolutionDialog.value.key==='custom'?'Custom':RESOLUTION_PRESETS[resolutionDialog.value.key].label};if(mode==='scale')overlay.value.widgets=scaleLayout(overlay.value.widgets,overlay.value.resolution,next);overlay.value.resolution=next;resolutionDialog.value=null;snapshot()}</script>
<style scoped src="./overlays.css"></style>
<style src="../../widgets/widgets.css"></style>
